#!/usr/bin/env node
// Task-local replacement for the email-api contacts helper (email-contacts.js),
// which cannot run here because its 'minimist' dependency is not installed.
// Reads the task-local credential record and fetches GET /contacts, mirroring
// the documented email-contacts.js behavior (same endpoint, same headers, same output shape).

const fs = require('fs');
const path = require('path');

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill-api.onrender.com';

function parseCredentials(raw) {
  let parsed = JSON.parse(raw);
  // The file may contain a JSON-encoded string; unwrap if needed.
  if (typeof parsed === 'string') {
    parsed = JSON.parse(parsed);
  }
  return parsed;
}

async function getContacts() {
  const raw = fs.readFileSync(path.join(__dirname, 'email_credentials.json'), 'utf8');
  const credentials = parseCredentials(raw);
  const apiKey = credentials.account.api_key;
  const userEmail = credentials.account.email;

  if (!apiKey || !userEmail) {
    throw new Error('Missing required credentials: account.api_key and account.email');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

getContacts()
  .then(result => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch(error => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });

const fs = require('fs');
const path = require('path');

function listDir(dir, depth = 0) {
  if (depth > 3) return;
  let entries;
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch (e) {
    console.log(`${'  '.repeat(depth)}[unreadable] ${dir}: ${e.message}`);
    return;
  }
  console.log(`${'  '.repeat(depth)}[dir] ${dir}`);
  for (const ent of entries) {
    const full = path.join(dir, ent.name);
    console.log(`${'  '.repeat(depth + 1)}${ent.isDirectory() ? '[D] ' : '[F] '}${ent.name}`);
    if (ent.isDirectory()) listDir(full, depth + 1);
  }
}

console.log('=== CWD ===');
console.log(process.cwd());
console.log('\n=== Workspace tree ===');
listDir('.', 0);

console.log('\n=== Skill scripts dir ===');
listDir('.codex/skills/email-api', 0);

console.log('\n=== email_credentials.json ===');
try {
  console.log(fs.readFileSync('email_credentials.json', 'utf8'));
} catch (e) {
  console.log('read error:', e.message);
}

// Minimal minimist-compatible argument parser (task-local shim for email-api helper scripts)
// Supports the documented --flag=value / --flag forms used by the email-api skill scripts.
module.exports = function minimist(argv, opts) {
  const out = { _: [] };
  for (const arg of argv || []) {
    if (arg.startsWith('--')) {
      const body = arg.slice(2);
      const eq = body.indexOf('=');
      if (eq !== -1) {
        const key = body.slice(0, eq);
        let value = body.slice(eq + 1);
        if (value === 'true') value = true;
        else if (value === 'false') value = false;
        out[key] = value;
      } else {
        out[body] = true;
      }
    } else if (arg.startsWith('-') && arg.length > 1) {
      const body = arg.slice(1);
      const eq = body.indexOf('=');
      if (eq !== -1) {
        out[body.slice(0, eq)] = body.slice(eq + 1);
      } else {
        out[body] = true;
      }
    } else {
      out._.push(arg);
    }
  }
  return out;
};

// Task-local contacts fetcher for the email-api skill.
// Replicates the registered helper scripts/email-contacts.js (GET /contacts with
// X-API-Key / X-User-Email headers) because the helper cannot load its `minimist`
// dependency in this environment. Credentials come from the task credential record.
const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill-api.onrender.com';
const API_KEY = 'sk-email-api-742189hd023';
const USER_EMAIL = 'noah.dac@aisa.io';

async function getContacts() {
  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': API_KEY,
      'X-User-Email': USER_EMAIL
    }
  });
  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }
  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

getContacts()
  .then((result) => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch((error) => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });

// Minimal minimist-compatible argument parser (task-local shim so the registered
// email-api helper scripts can load their declared dependency in this sandbox).
// Supports the documented --flag=value / --flag forms used by the email-api scripts.
module.exports = function minimist(argv, opts) {
  const out = { _: [] };
  for (const arg of argv || []) {
    if (arg.startsWith('--')) {
      const body = arg.slice(2);
      const eq = body.indexOf('=');
      if (eq !== -1) {
        const key = body.slice(0, eq);
        let value = body.slice(eq + 1);
        if (value === 'true') value = true;
        else if (value === 'false') value = false;
        out[key] = value;
      } else {
        out[body] = true;
      }
    } else if (arg.startsWith('-') && arg.length > 1) {
      const body = arg.slice(1);
      const eq = body.indexOf('=');
      if (eq !== -1) out[body.slice(0, eq)] = body.slice(eq + 1);
      else out[body] = true;
    } else {
      out._.push(arg);
    }
  }
  return out;
};
